class Solution:
    def trap(self, height: List[int]) -> int:
        n = len(height)
        res = 0
        # dp存储每个位置的lmax, rmax
        # 通过从左往右和从右往左两次遍历便捷实现
        lmax, rmax = [0] * n, [0] * n
        lmax[0] = height[0]
        for i in range(1, n):
            lmax[i] = max(height[i], lmax[i - 1])
        rmax[n-1] = height[n-1]
        for i in range(n-2, -1, -1):
            rmax[i] = max(height[i], rmax[i + 1])
        # 根据高度差得到每个位置接的雨水
        for i in range(n):
            min_max = min(lmax[i], rmax[i])
            if min_max > height[i]:
                res += min_max - height[i]
        return res
